package com.andye.warmod.block.entity;import com.andye.warmod.WarMod;import com.andye.warmod.block.*;import com.andye.warmod.radar.station.*;import java.util.*;import net.minecraft.SharedConstants;import net.minecraft.core.*;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.storage.*;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;
public final class RadarStationBlockEntity extends BlockEntity{private UUID radarId=UUID.randomUUID();private Direction facing=Direction.NORTH;private @Nullable UUID ownerId,primaryThreatId;private String ownerName="SERVER";private double warningRadius=256,fireRadius=500,primaryThreatDistance=Double.POSITIVE_INFINITY;private long phaseOffset,primaryThreatEstimatedImpactTime=Long.MAX_VALUE;private int redstoneSignal;private boolean warningActive,teardown;private final Map<UUID,RadarStationObservation> observations=new LinkedHashMap<>();public RadarStationBlockEntity(BlockPos p,BlockState s){super(ModBlockEntities.RADAR_STATION,p,s);if(s.hasProperty(RadarStationBlock.FACING))facing=s.getValue(RadarStationBlock.FACING);}public void initialize(ServerLevel l,Direction f,@Nullable Player o){radarId=UUID.randomUUID();facing=f;ownerId=o==null?null:o.getUUID();ownerName=o==null?"SERVER":o.getGameProfile().name();phaseOffset=RadarSweepMath.phaseOffset(radarId);sync();}public UUID radarId(){return radarId;}public Direction facing(){return facing;}public @Nullable UUID ownerId(){return ownerId;}public String ownerName(){return ownerName;}public double warningRadius(){return warningRadius;}public double fireRadius(){return fireRadius;}public int redstoneSignal(){return redstoneSignal;}public @Nullable UUID primaryThreatId(){return primaryThreatId;}public double primaryThreatDistance(){return primaryThreatDistance;}public long phaseOffset(){return phaseOffset;}public boolean warningActive(){return warningActive;}public int threatCount(){return(int)observations.values().stream().filter(RadarStationObservation::threatensWarningZone).count();}public Collection<RadarStationObservation> observations(){return List.copyOf(observations.values());}public void setTeardownInProgress(boolean v){teardown=v;}public boolean teardownInProgress(){return teardown;}
public void configure(double warning,double fire){warningRadius=clampRadius(warning);fireRadius=clampRadius(fire);if(level instanceof ServerLevel l){Vec3 c=Vec3.atCenterOf(worldPosition);observations.replaceAll((id,o)->{double dx=o.predictedImpactPosition().x-c.x,dz=o.predictedImpactPosition().z-c.z;return new RadarStationObservation(o.trackId(),o.trackSnapshot(),o.observedPosition(),o.observedVelocity(),o.predictedImpactPosition(),o.observationGameTime(),o.observedRouteTime(),dx*dx+dz*dz<=warningRadius*warningRadius);});recalculate(l);}RadarStationManager.updateRecord(this);sync();}public void setWarningRadius(double v){configure(v,fireRadius);}public boolean observe(ServerLevel l,RadarStationObservation o){observations.put(o.trackId(),o);while(observations.size()>RadarStationConstants.MAX_OBSERVATIONS)observations.remove(observations.keySet().iterator().next());return recalculate(l);}public boolean prune(ServerLevel l,long now,Set<UUID> active){observations.values().removeIf(o->!active.contains(o.trackId())||now-o.observationGameTime()>RadarStationConstants.SWEEP_PERIOD_TICKS*2L);return recalculate(l);}
private boolean recalculate(ServerLevel l){int old=redstoneSignal;UUID oldPrimary=primaryThreatId;Vec3 c=Vec3.atCenterOf(worldPosition);RadarStationObservation best=null;int bestSignal=0;double bestDistance=Double.POSITIVE_INFINITY;long bestEta=Long.MAX_VALUE;for(var o:observations.values()){if(!o.threatensWarningZone())continue;double distance=Math.hypot(o.observedPosition().x-c.x,o.observedPosition().z-c.z);int signal=signal(distance);long eta=estimatedImpact(o);if(signal>bestSignal||signal==bestSignal&&(eta<bestEta||eta==bestEta&&(distance<bestDistance||distance==bestDistance&&(best==null||o.trackId().toString().compareTo(best.trackId().toString())<0)))){best=o;bestSignal=signal;bestDistance=distance;bestEta=eta;}}redstoneSignal=Math.max(0,Math.min(15,bestSignal));warningActive=redstoneSignal>0;primaryThreatId=best==null?null:best.trackId();primaryThreatDistance=bestDistance;primaryThreatEstimatedImpactTime=bestEta;boolean changed=old!=redstoneSignal||!Objects.equals(oldPrimary,primaryThreatId);if(old!=redstoneSignal){for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)l.updateNeighborsAt(worldPosition.offset(x,0,z),getBlockState().getBlock());if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Radar station {} signal changed: old={}, new={}, primary={}",radarId,old,redstoneSignal,primaryThreatId);}if(changed)sync();return changed;}private int signal(double distance){if(distance<=fireRadius)return 15;double denominator=RadarStationConstants.DETECTION_RANGE_BLOCKS-fireRadius;if(denominator<=0)return 14;double n=Math.max(0,Math.min(1,(RadarStationConstants.DETECTION_RANGE_BLOCKS-distance)/denominator)),smooth=n*n*(3-2*n);return Math.max(1,Math.min(14,1+(int)Math.floor(smooth*13)));}private static long estimatedImpact(RadarStationObservation o){return o.trackSnapshot().terminalPlan().map(p->p.launchGameTime()+p.flightTicks()).orElseGet(()->o.trackSnapshot().carrierPlan().map(p->p.launchGameTime()+p.ignitionTicks()+p.boostTicks()+p.coastTicks()).orElse(Long.MAX_VALUE));}private static double clampRadius(double v){double c=Math.max(16,Math.min(4096,v));return Math.round(c/16)*16.0;}public void sync(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}
@Override protected void saveAdditional(ValueOutput o){super.saveAdditional(o);o.store("radar_id",UUIDUtil.CODEC,radarId);o.putString("facing",facing.getSerializedName());o.storeNullable("owner_id",UUIDUtil.CODEC,ownerId);o.putString("owner_name",ownerName);o.putDouble("warning_radius",warningRadius);o.putDouble("fire_radius",fireRadius);o.putLong("phase_offset",phaseOffset);o.putInt("redstone_signal",redstoneSignal);}@Override protected void loadAdditional(ValueInput i){super.loadAdditional(i);radarId=i.read("radar_id",UUIDUtil.CODEC).orElseGet(UUID::randomUUID);facing=Direction.byName(i.getStringOr("facing","north"));if(facing==null||!facing.getAxis().isHorizontal())facing=Direction.NORTH;ownerId=i.read("owner_id",UUIDUtil.CODEC).orElse(null);ownerName=i.getStringOr("owner_name","SERVER");warningRadius=clampRadius(i.getDoubleOr("warning_radius",256));fireRadius=clampRadius(i.getDoubleOr("fire_radius",500));phaseOffset=i.getLongOr("phase_offset",RadarSweepMath.phaseOffset(radarId));redstoneSignal=Math.max(0,Math.min(15,i.getIntOr("redstone_signal",0)));warningActive=redstoneSignal>0;}@Override public @Nullable Packet<ClientGamePacketListener> getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public net.minecraft.nbt.CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider p){return saveCustomOnly(p);}}